import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import type { HTMLAttributes } from "react";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "./utils";

const badgeStyles = tv({
  base: "inline-flex min-h-7 w-fit max-w-full shrink-0 items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium leading-4 tracking-normal [overflow-wrap:anywhere] shadow-[var(--shadow-card)] ring-1 forced-colors:border [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      neutral: "bg-secondary text-secondary-foreground ring-border",
      accent: "bg-accent text-accent-foreground ring-primary/15",
      success: "bg-success-subtle text-success-foreground ring-success/15",
      warning: "bg-warning-subtle text-warning-foreground ring-warning/20",
      error: "bg-card text-destructive ring-destructive/25",
      outline: "bg-transparent text-foreground ring-border",
    },
  },
  defaultVariants: { variant: "neutral" },
});

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: NonNullable<VariantProps<typeof badgeStyles>["variant"]>;
  dot?: boolean;
}

export function Badge({
  variant = "neutral",
  dot = false,
  className,
  children,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant}
      className={badgeStyles({ variant, className })}
      {...props}
    >
      {dot && <BadgeDot />}
      {children}
    </span>
  );
}

export function BadgeDot({
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      aria-hidden="true"
      {...props}
      data-slot="badge-dot"
      className={cn(
        "size-1.5 shrink-0 rounded-full bg-current forced-colors:bg-[CanvasText]",
        className,
      )}
    />
  );
}

import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

export function edgeOffset(placement: string | null, distance: number) {
  switch (placement) {
    case "top":
      return { x: 0, y: distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: -distance };
  }
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  ProgressBar as AriaProgressBar,
  type ProgressBarProps as AriaProgressBarProps,
  composeRenderProps,
  Label,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";

export interface ProgressBarProps
  extends Omit<AriaProgressBarProps, "className" | "children"> {
  label?: string;
  ref?: React.Ref<HTMLDivElement>;
  className?: AriaProgressBarProps["className"];
  children?: AriaProgressBarProps["children"];
}

export function ProgressBar({
  label,
  className,
  children,
  ...props
}: ProgressBarProps) {
  const reduceMotion = useReducedMotion();
  return (
    <AriaProgressBar
      {...props}
      data-slot="progress-bar"
      className={composeRenderProps(className, (className) =>
        cn("grid w-full gap-2", className),
      )}
    >
      {children ??
        (({ percentage, valueText, isIndeterminate }) => (
          <>
            {(label || !isIndeterminate) && (
              <div className="flex items-baseline gap-3 text-sm">
                {label && (
                  <Label
                    data-slot="progress-bar-label"
                    className="min-w-0 font-medium text-foreground [overflow-wrap:anywhere]"
                  >
                    {label}
                  </Label>
                )}
                {!isIndeterminate && (
                  <span
                    data-slot="progress-bar-value"
                    className="ms-auto shrink-0 font-mono tabular-nums text-muted-foreground"
                  >
                    {valueText}
                  </span>
                )}
              </div>
            )}
            <div
              data-slot="progress-bar-track"
              className="h-2 overflow-hidden rounded-full bg-secondary shadow-[var(--shadow-inset)] forced-colors:border rtl:-scale-x-100"
            >
              {isIndeterminate ? (
                <motion.div
                  key="indeterminate"
                  data-slot="progress-bar-fill"
                  className="h-full w-1/3 rounded-full bg-primary forced-colors:bg-[Highlight]"
                  initial={false}
                  animate={{ x: reduceMotion ? "100%" : ["-100%", "300%"] }}
                  transition={
                    reduceMotion
                      ? { duration: 0 }
                      : { duration: 1.6, repeat: Infinity, ease: "linear" }
                  }
                />
              ) : (
                <motion.div
                  key="determinate"
                  data-slot="progress-bar-fill"
                  className="h-full w-full origin-left rounded-full bg-primary forced-colors:bg-[Highlight]"
                  initial={false}
                  animate={{ scaleX: (percentage ?? 0) / 100 }}
                  transition={{
                    duration: reduceMotion ? 0 : duration.base,
                    ease: easeOut,
                  }}
                />
              )}
            </div>
          </>
        ))}
    </AriaProgressBar>
  );
}

"use client";

import {
  ChartLineUpIcon,
  GearSixIcon,
  HouseIcon,
  PackageIcon,
  ReceiptIcon,
  UsersIcon,
} from "@phosphor-icons/react";
import { Badge } from "../../../components/vip-ui/badge";
import { ProgressBar } from "../../../components/vip-ui/progress-bar";
import { cn } from "../../../components/vip-ui/utils";

const navigation = [
  { label: "Overview", href: "#", icon: HouseIcon, current: true },
  { label: "Orders", href: "#", icon: ReceiptIcon, count: 12 },
  { label: "Customers", href: "#", icon: UsersIcon },
  { label: "Products", href: "#", icon: PackageIcon },
  { label: "Reports", href: "#", icon: ChartLineUpIcon },
  { label: "Settings", href: "#", icon: GearSixIcon },
];

export function AppSidebar({ onNavigate }: { onNavigate?: () => void }) {
  return (
    <div className="flex h-full flex-col gap-6">
      <div className="flex items-center gap-2.5 px-2">
        <span
